pub(crate) fn check_function_shape_member(bound: &str) -> Option<String> {
    if bound == "Struct" { return Some("fields".to_owned()); }
    if bound == "Enum" { return Some("variants".to_owned()); }
    None
}

pub(crate) fn check_function_walks_the_fields_of(here: &ParsedView<'_, '_, '_, '_, '_, '_>, body: &Block, parameter: &str, shape: &str) -> bool {
    for expr in visited_in_block(body) {
        match expr {
            Expr::Path(segments, _) => {
                if segments.len() == 2 {
                    let ty = here.text(*nikaia_std::index::get(&segments, 0));
                    let member = here.text(*nikaia_std::index::get(&segments, 1));
                    if ty == parameter && (member == shape || member == "attribute" || member == "attributes") { return true; }
                }
            },
            _ => { },
        }
    }
    false
}

